const $=id=>document.getElementById(id);let lang='en',state={...defaults},selected=null,preset='custom',epoch=0;
try{lang=localStorage.getItem('kajicho-language-20261017')||'en';state=cleanState(JSON.parse(localStorage.getItem('kajicho-v2')||'{}'));}catch{}if(!strings[lang])lang='en';
const t=(k,v)=>translate(lang,k,v),number=(x,d=0)=>new Intl.NumberFormat({zh:'zh-CN',en:'en-US',ja:'ja-JP'}[lang],{minimumFractionDigits:d,maximumFractionDigits:d}).format(x);
function localize(){if(!$('loading').hidden){$('loading').textContent=t('loading');$('metricNote').textContent=t('loading');}document.documentElement.lang={zh:'zh-CN',en:'en',ja:'ja'}[lang];document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang));});$('before').setAttribute('aria-label',t('before')+' 3D');$('after').setAttribute('aria-label',t('after')+' 3D');const names=['north','northeast','east','southeast','south','southwest','west','northwest'];$('bearing').replaceChildren(...names.map((n,i)=>new Option(`${t(n)} · ${i*45}°`,i*45)));syncInputs();}
function syncInputs(){$('metricLabel').textContent=t(state.mode+'Metric');$('explanation').textContent=t(state.mode+'Explanation');const labelKeys={count:'treeCount',radius:'radius',crownHeight:'treeHeight',hour:'hour',height:'height',eui:'eui',saving:'saving',pv:'pv',factor:'factor',opacity:'opacity',playback:'speed',contrast:'contrast'};for(const [id,key] of Object.entries(labelKeys))$(id).setAttribute('aria-label',t(key));state.crownHeight=Math.max(state.radius+1,state.crownHeight);$('crownHeight').min=state.radius+1;for(const [k,v] of Object.entries(state)){const el=$(k);if(el&&('value' in el))el.value=v;} $('preset').value=preset;const units={count:t('unitTrees'),radius:'m',crownHeight:'m',hour:':00 JST',height:'×',eui:'kWh/m²',saving:'%',pv:'%',factor:'kg CO₂/kWh',opacity:'%',playback:'×',contrast:'×'};for(const [k,u] of Object.entries(units)){let v=k==='opacity'?Math.round(state[k]*100):state[k];$(k+'Value').textContent=`${v}${k==='hour'?'':' '}${u}`;}document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-selected',String(b.dataset.mode===state.mode));});document.querySelectorAll('[data-for]').forEach(e=>e.hidden=!e.dataset.for.split(' ').includes(state.mode));document.querySelector('.display-controls').hidden=state.mode!=='wind';$('contrastRow').hidden=state.field!=='difference';$('play').hidden=state.mode!=='wind';$('play').textContent=(state.playing?'Ⅱ ':'▷ ')+t(state.playing?'pause':'play');$('scope').textContent=t(state.mode+'Scope');$('treeSummary').textContent=t('treeSummary',{count:state.count,radius:state.radius});$('proposalTag').textContent=state.mode==='wind'&&state.field==='difference'?t('difference'):t('proposal');}
localize();
async function json(path){const r=await fetch(path);if(!r.ok)throw Error(path+': '+r.status);return r.json();}
async function binary(path){const r=await fetch(path);if(!r.ok)throw Error(path+': '+r.status);return r.arrayBuffer();}
let city,windCatalog,shadeCatalog,shadeData,coreMask;
try{[city,windCatalog,shadeCatalog,shadeData,coreMask]=await Promise.all([json('data/city.json'),json('data/wind-v2.json'),json('data/shade-v2.json'),binary('data/shade-v2.bin'),binary('data/core-mask.bin')]);coreMask=new Uint8Array(coreMask);}catch(e){$('loading').textContent=t('error');throw e;}
const meta=city.meta,N=meta.nx*meta.ny,coreBuildings=city.buildings.filter(b=>b.core),floorArea=coreBuildings.reduce((a,b)=>a+b.area*b.levels,0),views=[],clock=new THREE.Clock(),windCache=new Map();let activeFields=null,shadeFields=null,metrics=null,syncing=false;
const C=x=>new THREE.Color(x),windColors=['#182b49','#195f90','#279fbb','#73d6ca','#ddec8a','#e9ad58'].map(C);
function ramp(value){const x=Math.max(0,Math.min(2,value))/2*(windColors.length-1),i=Math.min(windColors.length-2,Math.floor(x));return windColors[i].clone().lerp(windColors[i+1],x-i);}
function diffRamp(value){const x=Math.max(-1,Math.min(1,value));return C('#28383e').lerp(C(x<0?'#39b1dc':'#ef9b60'),Math.abs(x));}
function carbonColor(value){return C('#465259').lerp(C('#eabf78'),Math.min(1,value/250));}
function cleanRing(ring){const a=[];for(const [x,y] of ring)if(!a.length||a.at(-1).distanceToSquared(new THREE.Vector2(x,y))>1e-10)a.push(new THREE.Vector2(x,y));if(a.length>1&&a[0].distanceToSquared(a.at(-1))<1e-10)a.pop();return a;}
const parts=[];
for(let i=0;i<city.buildings.length;i++){const b=city.buildings[i],s=new THREE.Shape(cleanRing(b.rings[0]));for(const hole of b.rings.slice(1)){const h=cleanRing(hole);if(h.length>=3&&Math.abs(THREE.ShapeUtils.area(h))>.1)s.holes.push(new THREE.Path(h));}const g=new THREE.ExtrudeGeometry(s,{depth:b.h,bevelEnabled:false,steps:1,curveSegments:1});g.rotateX(-Math.PI/2);const n=g.attributes.position.count;g.setAttribute('color',new THREE.BufferAttribute(new Float32Array(n*3),3));g.setAttribute('building',new THREE.BufferAttribute(new Float32Array(n).fill(i),1));parts.push(g);}
const merged=mergeGeometries(parts,false);parts.forEach(g=>g.dispose());
function addLines(scene,paths,color,y,opacity){const pos=[];for(const path of paths)for(let i=1;i<path.length;i++)pos.push(path[i-1][0],y,-path[i-1][1],path[i][0],y,-path[i][1]);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));const l=new THREE.LineSegments(g,new THREE.LineBasicMaterial({color,transparent:true,opacity,depthWrite:false}));scene.add(l);return l;}
function makeView(id,after){const el=$(id),scene=new THREE.Scene();scene.background=C('#151e25');const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setSize(el.clientWidth,el.clientHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;el.appendChild(renderer.domElement);const aspect=el.clientWidth/el.clientHeight,camera=new THREE.OrthographicCamera(-450*aspect,450*aspect,450,-450,1,4000);camera.position.set(650,1000,780);camera.zoom=1.4;camera.updateProjectionMatrix();const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(20,0,-135);controls.enableDamping=true;controls.dampingFactor=.12;controls.minZoom=.65;controls.maxZoom=8;controls.maxPolarAngle=Math.PI*.46;controls.minPolarAngle=.01;controls.update();controls.saveState();scene.add(new THREE.HemisphereLight('#c9e1e8','#253039',1.1));const light=new THREE.DirectionalLight('#e1e9e3',1.45);light.position.set(-300,800,300);scene.add(light);
const geometry=merged.clone(),originalPositions=new Float32Array(geometry.attributes.position.array),mesh=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.95,flatShading:true,transparent:true,opacity:.8,depthWrite:false}));scene.add(mesh);
const plane=new THREE.Mesh(new THREE.PlaneGeometry(meta.nx*meta.dx,meta.ny*meta.dx),new THREE.MeshBasicMaterial({color:0xffffff}));plane.rotation.x=-Math.PI/2;plane.position.set(meta.x0+meta.nx*meta.dx/2,-.5,-(meta.y0+meta.ny*meta.dx/2));scene.add(plane);addLines(scene,city.roads,'#7896a2',.05,.17);addLines(scene,city.rail,'#afc1c7',.12,.4);const boundary=city.boundary.type==='Polygon'?[city.boundary.coordinates]:city.boundary.coordinates;addLines(scene,boundary.flatMap(p=>p),'#d2e995',.3,.7);
const trees=new THREE.Group();scene.add(trees);let crowns,trunks;if(after){crowns=new THREE.InstancedMesh(new THREE.SphereGeometry(1,10,8),new THREE.MeshStandardMaterial({color:'#b6d783',roughness:1,flatShading:true}),48);trunks=new THREE.InstancedMesh(new THREE.CylinderGeometry(.45,.6,1,5),new THREE.MeshStandardMaterial({color:'#928d73',roughness:1}),48);trees.add(crowns,trunks);}
const count=1300,positions=new Float32Array(count*6),particleGeometry=new LineSegmentsGeometry();particleGeometry.setPositions(positions);const material=new LineMaterial({color:'#d9fca9',linewidth:1.7,transparent:true,opacity:.93,depthWrite:false,depthTest:true});material.resolution.set(el.clientWidth,el.clientHeight);const particles=new LineSegments2(particleGeometry,material);particles.frustumCulled=false;particles.renderOrder=3;scene.add(particles);const points=Array.from({length:count},(_,i)=>({x:0,y:0,age:0,seed:i+1}));const v={el,scene,renderer,camera,controls,mesh,originalPositions,plane,light,trees,crowns,trunks,particles,points,positions,after,compass:el.parentElement.querySelector('.compass')};views.push(v);
controls.addEventListener('change',()=>{if(syncing)return;syncing=true;for(const other of views)if(other!==v){other.camera.position.copy(camera.position);other.camera.quaternion.copy(camera.quaternion);other.camera.zoom=camera.zoom;other.camera.updateProjectionMatrix();other.controls.target.copy(controls.target);other.controls.update();}syncing=false;});
let down;el.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);el.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=el.getBoundingClientRect(),p=new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),ray=new THREE.Raycaster();ray.setFromCamera(p,camera);const hit=ray.intersectObject(mesh)[0];if(hit){selected=Math.round(geometry.attributes.building.getX(hit.face.a));inspect();views.forEach(updateBuildings);}});
new ResizeObserver(()=>{const w=el.clientWidth,h=el.clientHeight;camera.left=-450*w/h;camera.right=450*w/h;camera.updateProjectionMatrix();renderer.setSize(w,h);material.resolution.set(w,h);}).observe(el);return v;}
makeView('before',false);makeView('after',true);merged.dispose();
async function getWind(key){if(!windCache.has(key)){const entry=windCatalog.cases.find(c=>c.key===key);if(!entry)throw Error('Missing case '+key);const promise=binary(entry.url).then(buffer=>{const a=new Float32Array(buffer);if(a.length!==2*N)throw Error('Wrong wind length');return {...entry,u:a.subarray(0,N),v:a.subarray(N)};}).catch(e=>{windCache.delete(key);throw e;});windCache.set(key,promise);}return windCache.get(key);}
function shadeCase(factor){const e=shadeCatalog.cases.find(c=>c.date===state.date&&c.hour===state.hour&&c.heightFactor===factor);if(!e)throw Error('Missing shade case');return {...e,array:new Uint8Array(shadeData,e.offset,e.length)};}
function drawGround(v){const buf=new Uint8Array(N*4),index=v.after?1:0;for(let k=0;k<N;k++){let c;if(state.mode==='wind'){const f=activeFields[index],speed=Math.hypot(f.u[k],f.v[k]);if(state.field==='difference'){const baseline=activeFields[0],delta=v.after?speed-Math.hypot(baseline.u[k],baseline.v[k]):0;c=diffRamp(delta/(.5/state.contrast));}else c=ramp(speed);}else if(state.mode==='shade'){c=C(shadeFields[index][k]?'#253b50':'#bb8f55');}else c=C('#1e2b34');buf[k*4]=Math.round(c.r*255);buf[k*4+1]=Math.round(c.g*255);buf[k*4+2]=Math.round(c.b*255);buf[k*4+3]=255;}
const texture=new THREE.DataTexture(buf,meta.nx,meta.ny,THREE.RGBAFormat);texture.colorSpace=THREE.LinearSRGBColorSpace;texture.magFilter=THREE.NearestFilter;texture.minFilter=THREE.NearestFilter;texture.needsUpdate=true;v.plane.material.map?.dispose();v.plane.material.map=texture;v.plane.material.needsUpdate=true;}
function updateBuildings(v){const g=v.mesh.geometry,a=g.attributes.color,ids=g.attributes.building,pos=g.attributes.position,palette=city.buildings.map((b,i)=>{if(i===selected)return C('#f0d891');if(state.mode==='carbon'&&b.core){const c=carbon(b.area*b.levels,state);return carbonColor(v.after?c.proposal:c.baseline);}return C(b.core?'#76828a':'#53616f');});for(let i=0;i<a.count;i++){const index=Math.round(ids.getX(i)),c=palette[index];a.setXYZ(i,c.r,c.g,c.b);pos.setY(i,v.originalPositions[i*3+1]*(v.after&&state.mode==='shade'&&city.buildings[index].core?state.height:1));}a.needsUpdate=true;pos.needsUpdate=true;g.computeBoundingSphere();v.mesh.material.opacity=state.mode==='wind'?state.opacity:1;v.mesh.material.depthWrite=state.mode!=='wind';v.particles.visible=state.mode==='wind';v.trees.visible=state.mode!=='carbon';if(v.after){const matrix=new THREE.Matrix4();for(let i=0;i<48;i++){const p=city.trees[i];matrix.compose(new THREE.Vector3(p.x,state.crownHeight,-p.y),new THREE.Quaternion(),new THREE.Vector3(state.radius,state.radius,state.radius));v.crowns.setMatrixAt(i,matrix);matrix.compose(new THREE.Vector3(p.x,state.crownHeight/2,-p.y),new THREE.Quaternion(),new THREE.Vector3(1,state.crownHeight,1));v.trunks.setMatrixAt(i,matrix);}v.crowns.count=v.trunks.count=state.count;v.crowns.instanceMatrix.needsUpdate=v.trunks.instanceMatrix.needsUpdate=true;v.crowns.computeBoundingSphere();v.trunks.computeBoundingSphere();}}
function rand(p){p.seed=(1664525*p.seed+1013904223)>>>0;return p.seed/4294967296;}
function sample(f,x,y){const i=Math.floor((x-meta.x0)/meta.dx),j=Math.floor((y-meta.y0)/meta.dx);if(i<0||j<0||i>=meta.nx||j>=meta.ny)return null;const k=j*meta.nx+i;return [f.u[k],f.v[k]];}
function respawn(p,f){for(let tries=0;tries<150;tries++){p.x=meta.x0+rand(p)*meta.nx*meta.dx;p.y=meta.y0+rand(p)*meta.ny*meta.dx;const u=sample(f,p.x,p.y);if(u&&Math.hypot(...u)>.003)break;}p.age=3+rand(p)*7;}
function resetParticles(){if(!activeFields)return;for(const v of views){v.points.forEach((p,i)=>{p.seed=i+12491;respawn(p,activeFields[v.after?1:0]);});updateParticles(v,0);}}
function updateParticles(v,dt){if(!activeFields)return;const f=activeFields[v.after?1:0];v.points.forEach((p,i)=>{p.age-=dt;let uv=sample(f,p.x,p.y);if(p.age<0||!uv||Math.hypot(...uv)<.001){respawn(p,f);uv=sample(f,p.x,p.y)||[0,0];}const speed=Math.hypot(...uv),den=Math.max(speed,.0001),displaySpeed=state.playback*(12+Math.min(2,speed)*36),nx=p.x+uv[0]/den*dt*displaySpeed,ny=p.y+uv[1]/den*dt*displaySpeed,next=sample(f,nx,ny);if(!next||Math.hypot(...next)<.001){respawn(p,f);uv=sample(f,p.x,p.y)||[0,0];}else{p.x=nx;p.y=ny;}const d=Math.max(Math.hypot(...uv),.0001),len=9+Math.min(2,speed)*8,k=i*6;v.positions[k]=p.x;v.positions[k+1]=3;v.positions[k+2]=-p.y;v.positions[k+3]=p.x-uv[0]/d*len;v.positions[k+4]=3;v.positions[k+5]=-p.y+uv[1]/d*len;});const buf=v.particles.geometry.attributes.instanceStart.data;buf.array.set(v.positions);buf.needsUpdate=true;}
function updateText(){syncInputs();$('metricLabel').textContent=t(state.mode+'Metric');$('explanation').textContent=t(state.mode+'Explanation');const before=metrics?.before||0,after=metrics?.after||0;let a,b,change,note;if(state.mode==='wind'){a=number(before,3)+'×';b=number(after,3)+'×';change=(metrics.change>=0?'+':'')+number(metrics.change,2)+'%';note=t('windSmall');$('methodCaption').textContent=t('windNote',{count:56});$('legendLabel').textContent=t(state.field==='difference'?'differenceLegend':'windLegend');const range=.5/state.contrast;$('legendRange').textContent=state.field==='difference'?`−${range.toFixed(3)} / 0 / +${range.toFixed(3)}`:'0 / 1 / ≥2×';$('gradient').style.background=state.field==='difference'?'linear-gradient(90deg,#39b1dc,#28383e,#ef9b60)':'linear-gradient(90deg,#182b49,#279fbb,#73d6ca,#e9ad58)';}else if(state.mode==='shade'){a=number(before*100,1)+'%';b=number(after*100,1)+'%';change=(after>=before?'+':'')+number((after-before)*100,1);note=t('shadeNote',{date:state.date,hour:state.hour,cells:2830});$('methodCaption').textContent=note;$('legendLabel').textContent=t('shadeLegend');$('legendRange').textContent=t('shadow')+' / '+t('light');$('gradient').style.background='linear-gradient(90deg,#253b50 0 50%,#bb8f55 50% 100%)';}else{a=number(before);b=number(after);change=number(metrics.change,1)+'%';note='t CO₂ '+t('perYear');$('methodCaption').textContent=t('carbonNote',{area:number(floorArea)});$('legendLabel').textContent=t('carbonLegend');$('legendRange').textContent='0 / ≥250';$('gradient').style.background='linear-gradient(90deg,#465259,#eabf78)';}$('beforeMetric').textContent=a;$('afterMetric').textContent=b;$('deltaMetric').replaceChildren(document.createTextNode(change));if(state.mode==='shade'){const small=document.createElement('small');small.textContent=t('pp');$('deltaMetric').append(small);}$('metricNote').textContent=note;if(selected!==null)inspect();}
const usage={en:{'業務施設':'Office','共同住宅':'Apartment building','住宅':'House','商業施設':'Commercial','店舗等併用住宅':'Mixed retail and housing','作業所併用住宅':'Mixed workshop and housing','運輸倉庫施設':'Transport / storage','官公庁施設':'Government','供給処理施設':'Utilities','工場':'Factory','文教厚生施設':'Education / welfare','宿泊施設':'Hotel','その他':'Other','不明':'Unknown'},zh:{'業務施設':'办公建筑','共同住宅':'集合住宅','住宅':'住宅','商業施設':'商业建筑','店舗等併用住宅':'商住建筑','作業所併用住宅':'作坊兼住宅','運輸倉庫施設':'运输仓储','官公庁施設':'政府设施','供給処理施設':'市政设施','工場':'工厂','文教厚生施設':'文教福利设施','宿泊施設':'住宿设施','その他':'其他','不明':'未知'}};
function inspect(){if(selected===null)return;const b=city.buildings[selected],c=carbon(b.area*b.levels,state);$('buildingTitle').textContent=(lang==='ja'?b.usage:usage[lang]?.[b.usage])||t('unknownUsage');const rows=[[b.core?t('core'):t('context'),b.id.replace('bldg_','').slice(0,8)],[t('heightLabel'),number(b.h,1)+' m · '+t(b.height_source==='bldg:measuredHeight'?'source':'estimated')],[t('levels'),b.levels+' '+t('floor')+' · '+t(b.levels_source==='source'?'source':'estimated')],[t('area'),number(b.area)+' m²'],[t('survey'),b.survey==='0001'?t('unknown'):b.survey],[t('electricity'),number(c.baseline,1)+' t CO₂ '+t('perYear')]];if(state.mode==='shade'&&b.core)rows.push([t('proposalValue')+' / '+t('heightLabel'),number(b.h*state.height,1)+' m']);$('buildingBody').replaceChildren(...rows.map(([a,b])=>{const e=document.createElement('div');e.className='buildingrow';const label=document.createElement('span'),value=document.createElement('b');label.textContent=a;value.textContent=b;e.append(label,value);return e;}));}
async function refresh(){const request=++epoch;metrics=null;for(const id of ['beforeMetric','afterMetric','deltaMetric'])$(id).textContent='…';$('metricNote').textContent=t('loading');$('save').disabled=true;syncInputs();$('loading').hidden=false;$('loading').textContent=t('loading');try{if(state.mode==='wind'){const pair=await Promise.all([getWind(windKey(state,true)),getWind(windKey(state))]);if(request!==epoch)return;activeFields=pair;metrics={before:pair[0].core_mean,after:pair[1].core_mean,change:pair[1].relative_mean_change_pct};resetParticles();}else if(state.mode==='shade'){const base=shadeCase(1),proposal=shadeCase(state.height);shadeFields=[base.array,treeShade(proposal.array,meta,city.trees,state,proposal)];metrics={before:fraction(shadeFields[0],coreMask),after:fraction(shadeFields[1],coreMask)};const alt=base.altitude,az=base.azimuth;for(const v of views)v.light.position.set(-Math.sin(az)*Math.cos(alt)*1000,Math.sin(alt)*1000,Math.cos(az)*Math.cos(alt)*1000);}else{const c=carbon(floorArea,state);metrics={before:c.baseline,after:c.proposal,change:c.change};}if(request!==epoch)return;for(const v of views){drawGround(v);updateBuildings(v);}updateText();$('loading').hidden=true;$('save').disabled=false;try{localStorage.setItem('kajicho-v2',JSON.stringify(state));}catch{}}catch(e){if(request===epoch)$('loading').textContent=t('error');console.error(e);}}
for(const b of document.querySelectorAll('[data-lang]'))b.addEventListener('click',()=>{lang=b.dataset.lang;localStorage.setItem('kajicho-language-20261017',lang);localize();if(metrics)updateText();});
for(const b of document.querySelectorAll('[data-mode]'))b.addEventListener('click',()=>{state.mode=b.dataset.mode;refresh();});
for(const key of ['bearing','count','radius','date','hour','crownHeight','height','eui','saving','pv','factor','field','contrast','opacity','playback'])$(key).addEventListener(['bearing','date','field'].includes(key)?'change':'input',e=>{state[key]=['date','field'].includes(key)?e.target.value:Number(e.target.value);preset='custom';if(['opacity','playback'].includes(key)){syncInputs();views.forEach(updateBuildings);try{localStorage.setItem('kajicho-v2',JSON.stringify(state));}catch{}}else refresh();});
$('preset').addEventListener('change',e=>{preset=e.target.value;if(preset==='existing')Object.assign(state,{count:0,height:1,saving:0,pv:0});if(preset==='green')Object.assign(state,{count:48,radius:4,crownHeight:8,height:1,saving:0,pv:0});if(preset==='mixed')Object.assign(state,{count:48,radius:6,crownHeight:9,height:.75,saving:30,pv:20});refresh();});
$('play').addEventListener('click',()=>{state.playing=!state.playing;syncInputs();});$('viewReset').addEventListener('click',()=>views[0].controls.reset());$('topView').addEventListener('click',()=>{const v=views[0];v.camera.position.set(v.controls.target.x,.001+1200,v.controls.target.z+.1);v.controls.update();});$('reset').addEventListener('click',()=>{const mode=state.mode;state={...defaults,mode};preset='custom';selected=null;$('buildingTitle').textContent=t('pick');$('buildingBody').textContent=t('pickText');refresh();});
for(const id of ['sourcesBtn','methodsLink'])$(id)?.addEventListener('click',()=>$('sources').showModal());$('closeSources').addEventListener('click',()=>$('sources').close());
$('save').addEventListener('click',()=>{const result={version:2,language:lang,place:'Kajicho 1 & 2',createdAt:new Date().toISOString(),parameters:state,metric:metrics,units:state.mode==='wind'?'relative speed':state.mode==='shade'?'fraction of open ground':'t CO2/year',windCase:windKey(state),shadeMethod:shadeCatalog.method,coreBuildings:277,coreFloorAreaProxy:floorArea,scope:t(state.mode+'Scope'),interpretation:t(state.mode+'Explanation'),dataSources:'data/provenance.json'};const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`Kajicho_Scenario_v2_${lang}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
await refresh();document.querySelectorAll('button,select,input').forEach(e=>e.disabled=false);document.body.dataset.ready='true';function animate(){requestAnimationFrame(animate);const dt=Math.min(.045,clock.getDelta());for(const v of views){v.controls.update();if(state.playing&&state.mode==='wind'&&$('loading').hidden)updateParticles(v,dt);const a=new THREE.Vector3(0,0,0).project(v.camera),n=new THREE.Vector3(0,0,-100).project(v.camera);v.compass.style.transform=`rotate(${Math.atan2((n.x-a.x)*v.el.clientWidth,(n.y-a.y)*v.el.clientHeight)}rad)`;v.renderer.render(v.scene,v.camera);}}animate();
window.demoInfo={version:2,buildingCount:1981,windCases:windCatalog.cases.length,shadeCases:shadeCatalog.cases.length};
